{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "노상주차장 관광버스 전용주차구획의 보조표지 설치 의무 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "관광버스 전용주차구획에는 보조표지를 반드시 설치해야 하는 것은 아니다. 조례 제14조의2제2항은 관광버스 전용주차구획에 노상주차장 이용에 관한 안내표지를 설치하고, 보조표지를 잘 보이게 설치할 수 있다고 정하고 있다. 따라서 보조표지는 설치 의무가 아니라 설치 가능한 사항이다.",
          "b_ids": "주차장:제14조의2제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "노상주차장 관광버스 전용주차구획 이용 안내표지에 주차장 사용시간 기재 필요 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "이용 안내표지에는 주차장 사용시간을 적어야 한다. 조례 제15조제2항은 노상주차장 이용에 관한 안내표지에 주차장의 사용시간을 기재한 내용을 이용자가 쉽게 볼 수 있는 장소에 설치하여야 한다고 정하고 있다. 관광버스 전용주차구획에도 제14조의2제2항에 따라 이 안내표지를 설치하므로, 사용시간을 기재하여야 한다.",
          "b_ids": "주차장:제15조제2항, 주차장:제15조제2항제3호, 주차장:제14조의2제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
